@import url(https://whuuayu.github.io/krunker-classic-css/classic.css);

/*Make Edits Below*/

/* Client Edits */

div#PC7WaterMark2 {
    display: none !important;
}

div#tcStringBtn {
    display: none !important;
}

#PC7WaterMark1, #matchInfo {
    display: none;
}

#PC7WaterMark,#PC7WaterMark1,#PC7WaterMark2{display:none!important;visibility:hidden!important}

.toastify {
  background: #000000 !important;
  box-shadow: none;
  font-size: 0px;
}
.toastify::after {
  content: "<3";
  font-size: 1vh;
}

#nukeCounter {
    background-color: rgb(20 20 20 / 0%) !important;
    text-shadow: 3px 3px black !important;
}

a {
	color: #6c23ff;
}

.button.lgn[onclick*="openDiscord"] {
  display: none !important;
}

.button.buttonG.lgn {
    display: none;
}

.button.buttonP.lgn::after {
  content: "idk";
  color: white;
  font-weight: bold;
  display: block;
  text-align: center;
  padding: 5px;
}

div#PC7TwitchLink {
    display: none;
}

/* Pic */

#profilePicM {
    border: 4px solid Black;
    content: url(https://files.catbox.moe/shjbky.png);
    background-color: transparent;
    filter: none;
    filter: drop-shadow(0px 0px 5px black);
}
#menuMiniProfilePic, #profilePicM {
    content: url("https://files.catbox.moe/shjbky.png");
    border-radius: 1rem;
}

.endTablePfp {
    content: url("https://files.catbox.moe/shjbky.png");
}

/* FPS & Ping */

#fpsDisplay{
    color: transparent;
}

#pingDisplay {
    color: transparent;
}

#pingDisplay, #fpsDisplay {
    text-align: left
}

#pingText::after {
    content: url('https://i.imgur.com/a8lrnOx.png')!important;
    image-rendering: optimizequality;
    filter: blur(1px);
    color: #9eeb56;
    margin-left: 6px;
}

