/* Comp */

.compSwpTmB, #compBtnLst, #compClassPHolder, .compPLstIcn {
    border-radius: 0px;
    border: none !important;
    background-color: transparent !important;
}

.compMenBtnS {
    background-color: transparent !important;
    width: 76px;
    height: 86px;
    border-radius: 0px;
    border: none
}

#cmpDatBox, .compTScrB, .compPlWepsL, .cmpTmHed, .compPlWepsR   {
display: none !important;
}

.compClassPItm {
    width: 80px;
    height: 80px;
    border: none;
    border-radius: 0px;
    background-color: rgb(0 0 0 / 0%);
}

.compClassPCnt {
    bottom: -35px;
    right: 20px;
    color: #ffffff;
    text-shadow: none;
}

#compTimBox {
    position: absolute;
    width: 100%;
    bottom: 9px;
    text-align: center;
    color: rgb(255 255 255);
    font-size: 18px;
}

#instructionHolder {
    backdrop-filter: grayscale(1);
}

#popupContent {
    display: none !important;
}

#claimPop {
    display: none !important;
}

/*Some Tags For Sharp Shooter And Deposit, Etc.*/

#krTagHolder, #giftTagHolder, #powerUpHolder {
    background-color: transparent !important;
}

#krTagHolder {
    right: calc(100% - 999px);
    bottom: 1450px;
}

.killStreakItem, .killStreakItemInner {
    background-color: transparent!important;
}

