/* DEATH UI*/
.death-row-left,
.death-row-right,
.death-stats,
.death-row-center,
.death-row-class-level,
.death-row-user-stat,
.death-row-bottom-bg {
    display: none !important;
}

#uiBase.onDeathScrn #chatHolder {
    animation: none;
    left: 15px;
    bottom: 130px;
}

.death-ui-bottom,
.death-ui-bottom-empty {
    background: rgba(0, 0, 0, 0%);
    backdrop-filter: none;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 20px;
    animation: unset;
}

.death-row-user-text {
    display: flex;
    flex-direction: column;
    text-align: left;
    margin: 0;
    font-size: 20px;
    font-weight: bold;
    color: white;
    line-height: 1.5;
}

.death-row-user-text::before {
    content: "Killed by:";
    font-size: 16px;
    font-weight: normal;
    color: rgb(255, 255, 255);
    margin-bottom: 5px;
}


.death-row-bottom {
    height: 145px;
    width: 370px;
    position: relative;
    outline: none;
    background-color: rgba(0, 0, 0, 0.5) !important;
    filter: none;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    padding: 0 20px;
    gap: 20px;
    margin-left: 20px;
    animation: fadeIn 2s ease-in-out;
}
@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}


.death-row-class-img {
    height: 90px;
    width: 90px;
    content: var(--deathpic);
    border-radius: 2px;
    image-rendering: auto;
    bottom: -2px;
}

.death-column:nth-child(4) .death-row-bottom {
    display: none;
}

.death-row-center-self:not(:first-child) {
    display: none;
}

.death-row-center-self {
    font-size: 0!important;
    filter: none;
}

.death-row-center-self::after {
    content: url('https://files.catbox.moe/shjbky.png');
    margin-top: -150px;
    filter: invert(1);
}

